mapper.select:
SELECT id, title, business_type, method, request_method, operator_type, oper_name, dept_name, oper_url, oper_ip, oper_location, oper_param, json_result, status, error_msg, oper_time FROM sys_operation_log WHERE 1=1
AND oper_name LIKE CONCAT('%', #{operName}, '%')
AND business_type = #{businessType}
AND status = #{status}
AND oper_time >= #{startTime}
AND oper_time <= #{endTime}
AND title LIKE CONCAT('%', #{title}, '%')
ORDER BY oper_time DESC

SELECT COUNT(*)
FROM sys_operation_log
WHERE 1=1

    AND oper_name LIKE CONCAT('%', #{operName}, '%')


    AND business_type = #{businessType}


    AND status = #{status}


    AND oper_time >= #{startTime}


    AND oper_time <= #{endTime}


    AND title LIKE CONCAT('%', #{title}, '%')
